                  {=og_text(og_get($v_d, ['name']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'base', 'weight' => 'semibold', 'children' => (string) $c_2])|noescape}
                {capture $c_3}
                  {=og_text(og_get($v_d, ['weight']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
              {/capture}
              {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'children' => (string) $c_4])|noescape}
